-- The schema the migrations in migrations/ produce. Generated by
-- TestSchema; do not edit. Refresh it after adding a migration:
--   go test ./internal/store -run TestSchema -update

CREATE TABLE api_tokens (
    -- A UUIDv7: the handle the user sees and revokes the token by.
    id TEXT PRIMARY KEY CHECK (length(id) = 36),
    -- The hex SHA-256 of the token.
    token_hash TEXT NOT NULL CHECK (length(token_hash) = 64),
    user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    -- What the user calls it, such as "iPhone" or "Claude".
    name TEXT NOT NULL CHECK (name <> ''),
    -- What it may do: scopes separated by spaces (ingest, tools, read).
    scopes TEXT NOT NULL CHECK (scopes <> ''),
    created_at TEXT NOT NULL,
    -- When it was last used, to the hour or so; NULL until its first use.
    last_used_at TEXT
) STRICT;

CREATE UNIQUE INDEX api_tokens_token_hash ON api_tokens (token_hash);

CREATE INDEX api_tokens_user_id ON api_tokens (user_id);

CREATE TABLE days (
    user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    day TEXT NOT NULL CHECK (day GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
    -- Why the day is out of calibration; NULL when it is not.
    excluded_reason TEXT CHECK (excluded_reason <> ''),
    updated_at TEXT NOT NULL,
    PRIMARY KEY (user_id, day)
) STRICT;

CREATE TABLE events (
    -- A UUIDv7 the store makes: the order of the ids is the order of
    -- the writes.
    id TEXT NOT NULL CHECK (length(id) = 36),
    user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    at TEXT NOT NULL,
    actor TEXT NOT NULL CHECK (actor IN ('user', 'import')),
    client TEXT NOT NULL CHECK (client <> ''),
    -- The AI model that acted for the user, or ''.
    model TEXT NOT NULL DEFAULT '',
    operation TEXT NOT NULL CHECK (operation IN (
        'food.save', 'food.archive', 'meal.create', 'meal.replace', 'meal.delete',
        'day.exclude', 'day.include', 'metrics.merge', 'metric.set', 'metric.delete', 'undo'
    )),
    -- What changed: a food's or a meal's id, a day, a day and a metric,
    -- or for an undo the event it took back.
    entity TEXT NOT NULL CHECK (entity <> ''),
    -- The entity's state as JSON; NULL where there was none.
    before_state TEXT CHECK (before_state IS NULL OR json_valid(before_state)),
    after_state TEXT CHECK (after_state IS NULL OR json_valid(after_state)),
    -- The undo that took the event back.
    undone_by TEXT CHECK (undone_by IS NULL OR length(undone_by) = 36),
    -- 1 when the entity changed since (an import wrote it): undo cannot
    -- take the event back without losing that, and passes over it.
    stale INTEGER NOT NULL DEFAULT 0 CHECK (stale IN (0, 1)),
    PRIMARY KEY (user_id, id)
) STRICT;

CREATE INDEX events_user ON events (user_id);

CREATE INDEX events_user_entity ON events (user_id, entity);

CREATE TABLE food_aliases (
    food_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    alias TEXT NOT NULL CHECK (alias <> ''),
    alias_key TEXT NOT NULL CHECK (alias_key <> ''),
    PRIMARY KEY (user_id, food_id, alias_key),
    FOREIGN KEY (user_id, food_id) REFERENCES foods (user_id, id) ON DELETE CASCADE
) STRICT;

CREATE UNIQUE INDEX food_aliases_user_alias ON food_aliases (user_id, alias_key);

CREATE TABLE food_servings (
    food_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    name TEXT NOT NULL CHECK (name <> ''),
    name_key TEXT NOT NULL CHECK (name_key <> ''),
    -- In the food's unit, grams or ml.
    amount REAL NOT NULL CHECK (amount > 0),
    PRIMARY KEY (user_id, food_id, name_key),
    FOREIGN KEY (user_id, food_id) REFERENCES foods (user_id, id) ON DELETE CASCADE
) STRICT;

CREATE TABLE foods (
    -- A UUIDv7, chosen by the client that first saved the food. Ids are
    -- per user (the primary key is the pair), so another user's food
    -- under the same id is no row of this user's, and nothing tells it
    -- is there.
    id TEXT NOT NULL CHECK (length(id) = 36),
    user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name TEXT NOT NULL CHECK (name <> ''),
    brand TEXT NOT NULL DEFAULT '',
    -- name and brand as food.Key compares them: the same name and brand
    -- are the same food (see foods_user_name_brand).
    name_key TEXT NOT NULL CHECK (name_key <> ''),
    brand_key TEXT NOT NULL DEFAULT '',
    -- What the nutrients refer to: 100 g, 100 ml or one portion.
    basis TEXT NOT NULL CHECK (basis IN ('100g', '100ml', 'portion')),
    kcal REAL NOT NULL CHECK (kcal >= 0),
    protein REAL NOT NULL CHECK (protein >= 0),
    carbs REAL NOT NULL CHECK (carbs >= 0),
    fat REAL NOT NULL CHECK (fat >= 0),
    -- Optional nutrients, in grams like the macronutrients; NULL when
    -- unknown.
    fiber REAL CHECK (fiber >= 0),
    saturated_fat REAL CHECK (saturated_fat >= 0),
    sugars REAL CHECK (sugars >= 0),
    salt REAL CHECK (salt >= 0),
    polyols REAL CHECK (polyols >= 0),
    alcohol REAL CHECK (alcohol >= 0),
    -- The weight of one portion of a food per portion, when known.
    portion_g REAL CHECK (portion_g IS NULL OR (basis = 'portion' AND portion_g > 0)),
    -- recipe and off (Open Food Facts) are planned (DESIGN.md §4); they
    -- are allowed now, so adding them needs no rebuild of the table.
    source TEXT NOT NULL CHECK (source IN ('label', 'estimate', 'user', 'dish', 'recipe', 'off')),
    note TEXT NOT NULL DEFAULT '',
    archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1)),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    -- The child tables' foreign keys name the user as well, so a child
    -- row can never belong to another user's food.
    PRIMARY KEY (user_id, id)
) STRICT;

CREATE UNIQUE INDEX foods_user_name_brand ON foods (user_id, name_key, brand_key);

CREATE TRIGGER foods_fts_delete AFTER DELETE ON foods
BEGIN
    DELETE FROM foods_fts WHERE food_id = old.id AND user_id = old.user_id;
END;

CREATE VIRTUAL TABLE foods_fts USING fts5 (
    food_id UNINDEXED,
    user_id UNINDEXED,
    name,
    brand,
    aliases,
    tokenize = 'unicode61 remove_diacritics 2'
);

CREATE TABLE 'foods_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID;

CREATE TABLE 'foods_fts_content'(id INTEGER PRIMARY KEY, c0, c1, c2, c3, c4);

CREATE TABLE 'foods_fts_data'(id INTEGER PRIMARY KEY, block BLOB);

CREATE TABLE 'foods_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB);

CREATE TABLE 'foods_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;

CREATE TABLE meal_items (
    -- A UUIDv7 the client chose for a new item, or the store did; per
    -- user.
    id TEXT NOT NULL CHECK (length(id) = 36),
    meal_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    -- The item's place in the meal, from 0.
    position INTEGER NOT NULL CHECK (position >= 0),
    -- NULL for a one-off estimate.
    food_id TEXT,
    -- The food's name (with its brand) when logged, or the estimate's.
    name TEXT NOT NULL CHECK (name <> ''),
    -- The quantity as the client gave it: one of an amount with its unit,
    -- a number of a named serving, or a number of portions.
    quantity_amount REAL NOT NULL DEFAULT 0 CHECK (quantity_amount >= 0),
    quantity_unit TEXT NOT NULL DEFAULT '' CHECK (quantity_unit IN ('', 'g', 'ml')),
    quantity_servings REAL NOT NULL DEFAULT 0 CHECK (quantity_servings >= 0),
    quantity_serving TEXT NOT NULL DEFAULT '',
    quantity_portions REAL NOT NULL DEFAULT 0 CHECK (quantity_portions >= 0),
    -- The quantity in the food's unit, and the item's own nutrients.
    amount REAL NOT NULL CHECK (amount > 0),
    unit TEXT NOT NULL CHECK (unit IN ('g', 'ml', 'portion')),
    kcal REAL NOT NULL CHECK (kcal >= 0),
    protein REAL NOT NULL CHECK (protein >= 0),
    carbs REAL NOT NULL CHECK (carbs >= 0),
    fat REAL NOT NULL CHECK (fat >= 0),
    fiber REAL CHECK (fiber >= 0),
    saturated_fat REAL CHECK (saturated_fat >= 0),
    sugars REAL CHECK (sugars >= 0),
    salt REAL CHECK (salt >= 0),
    polyols REAL CHECK (polyols >= 0),
    alcohol REAL CHECK (alcohol >= 0),
    -- As foods.source, the planned recipe and off included.
    source TEXT NOT NULL CHECK (source IN ('label', 'estimate', 'user', 'dish', 'recipe', 'off')),
    note TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (user_id, id),
    FOREIGN KEY (user_id, meal_id) REFERENCES meals (user_id, id) ON DELETE CASCADE,
    -- Foods are archived, never deleted, while an item uses them.
    FOREIGN KEY (user_id, food_id) REFERENCES foods (user_id, id)
) STRICT;

CREATE UNIQUE INDEX meal_items_meal_position ON meal_items (user_id, meal_id, position);

CREATE INDEX meal_items_user_food ON meal_items (user_id, food_id);

CREATE TABLE meals (
    -- A UUIDv7 the client chose, so a retry of the same meal is one meal.
    -- Ids are per user, as for foods.
    id TEXT NOT NULL CHECK (length(id) = 36),
    user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    -- RFC 3339 in UTC, to the second, so the text sorts as the time.
    eaten_at TEXT NOT NULL CHECK (
        eaten_at GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]T[0-2][0-9]:[0-5][0-9]:[0-6][0-9]Z'
    ),
    -- The logical day (day.Calendar.DayOf), YYYY-MM-DD.
    day TEXT NOT NULL CHECK (day GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
    description TEXT NOT NULL DEFAULT '',
    client TEXT NOT NULL CHECK (client IN ('mcp', 'chat', 'web', 'telegram', 'import')),
    note TEXT NOT NULL DEFAULT '',
    -- meal.Meal.Fingerprint of what the client sent to create the meal:
    -- the same id with another fingerprint is another meal, not a retry.
    -- An edit leaves it, so a late retry of the create finds its meal.
    fingerprint TEXT NOT NULL CHECK (length(fingerprint) = 64),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    PRIMARY KEY (user_id, id)
) STRICT;

CREATE INDEX meals_user_day ON meals (user_id, day, eaten_at);

CREATE INDEX meals_user_eaten_at ON meals (user_id, eaten_at);

CREATE TABLE metrics (
    user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    -- The logical day, YYYY-MM-DD.
    day TEXT NOT NULL CHECK (day GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
    metric TEXT NOT NULL CHECK (metric IN (
        'weight', 'body_fat', 'lean_mass', 'steps', 'active_kcal', 'basal_kcal',
        'sleep_h', 'rhr', 'hrv', 'vo2max', 'exercise_min'
    )),
    value REAL NOT NULL,
    -- manual: the user gave it, and it beats an import.
    source TEXT NOT NULL CHECK (source IN ('manual', 'import')),
    updated_at TEXT NOT NULL,
    PRIMARY KEY (user_id, day, metric)
) STRICT;

CREATE TABLE schema_migrations (
	version    INTEGER PRIMARY KEY,
	name       TEXT    NOT NULL,
	checksum   TEXT    NOT NULL,
	applied_at TEXT    NOT NULL
) STRICT;

CREATE TABLE sessions (
    -- The hex SHA-256 of the session token.
    id TEXT PRIMARY KEY CHECK (length(id) = 64),
    user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at TEXT NOT NULL,
    -- When the user last used the session, to the hour or so: the server
    -- updates it at most once an hour.
    last_seen_at TEXT NOT NULL,
    -- The session ends here however active it is; the user signs in again.
    expires_at TEXT NOT NULL
) STRICT;

CREATE INDEX sessions_expires_at ON sessions (expires_at);

CREATE INDEX sessions_user_id ON sessions (user_id);

CREATE TABLE user_identities (
    issuer TEXT NOT NULL CHECK (issuer <> ''),
    subject TEXT NOT NULL CHECK (subject <> ''),
    user_id TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at TEXT NOT NULL,
    PRIMARY KEY (issuer, subject)
) STRICT;

CREATE UNIQUE INDEX user_identities_user_issuer ON user_identities (user_id, issuer);

CREATE TABLE users (
    -- A UUIDv7, in the canonical text form.
    id TEXT PRIMARY KEY CHECK (length(id) = 36),
    -- The sign-in name, in the form user.NormalizeEmail gives it.
    email TEXT NOT NULL CHECK (email <> ''),
    name TEXT NOT NULL CHECK (name <> ''),
    role TEXT NOT NULL CHECK (role IN ('admin', 'user')),
    -- An argon2id hash in the PHC string format. NULL means the user
    -- cannot sign in with a password (single sign-on comes later).
    password_hash TEXT,
    locale TEXT NOT NULL CHECK (locale <> ''),
    timezone TEXT NOT NULL CHECK (timezone <> ''),
    -- The hour at which the user's day starts: a meal before it belongs
    -- to the day before.
    day_start_hour INTEGER NOT NULL CHECK (day_start_hour BETWEEN 0 AND 23),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
) STRICT;

CREATE UNIQUE INDEX users_email ON users (email);
